text:
The linear estimator receives a Gaussian message from joint denoising.
This message has mean matrix $\mathbf X^{\rm pri}\in\mathbb C^{KN\times MN}$
and per-column covariance $\gamma\I_{KN}$, with $\gamma>0$.
For each column, the product of this message and the likelihood in
\eqref{eq:working-posterior} gives a Gaussian posterior.
The posterior mean matrix and per-column covariance are given by
\cite[Sec.~III-A]{cai2026}, \cite[eq.~(15c)]{ma2017}:
\begin{align}
 \mathbf X_{\rm L}
 &=\mathbf X^{\rm pri}
 +\gamma\widehat{\mathbf A}^{\mathsf H}
 (\widehat\sigma^2\I_Q+\gamma\widehat{\mathbf A}\widehat{\mathbf A}^{\mathsf H})^{-1}
 (\mathbf Y-\widehat{\mathbf A}\mathbf X^{\rm pri}),
 \label{eq:linear-mean}\\
 \bm\Sigma_{\rm L}
 &=(\gamma^{-1}\I_{KN}+\widehat\sigma^{-2}\widehat{\mathbf A}^{\mathsf H}\widehat{\mathbf A})^{-1},
 \qquad t_{\rm L}=\frac{\tr\bm\Sigma_{\rm L}}{KN}.
 \label{eq:linear-variance}
\end{align}

For message exchange, the posterior covariance is approximated by
$t_{\rm L}\I_{KN}$ \cite{ma2015,cai2026}.
Dividing this Gaussian approximation by the incoming message removes the
information supplied by joint denoising \cite{minka2001}.
The resulting extrinsic variance and mean are
\begin{equation}
 v_{\rm L}=(t_{\rm L}^{-1}-\gamma^{-1})^{-1},\qquad
 \mathbf R_{\rm L}=v_{\rm L}
 \left(\frac{\mathbf X_{\rm L}}{t_{\rm L}}
       -\frac{\mathbf X^{\rm pri}}{\gamma}\right).
 \label{eq:linear-extrinsic}
\end{equation}

Following \cite[Sec.~III-B]{cai2026}, we first derive the channel estimate
under the active hypothesis and the posterior activity probability, and then
combine them to estimate $X_k$.
Let $R_k$ and $v$ denote the input mean and variance.
For the channel tensor $H_k$, we define
$[\vect(H_k)]_{mN^2+rN+n}=H_{kmrn}$.
This Gaussian input message corresponds to the local observation model
\begin{equation}
 \begin{gathered}
 R_k=\alpha_k H_k+W_k,\qquad H_k\sim q_{\rm tr},\\
 \vect(W_k)\sim\CN(\mathbf0,v\I_D),\qquad D=MN^2.
 \end{gathered}
 \label{eq:pseudo-awgn}
\end{equation}

Under the active hypothesis $\alpha_k=1$, \eqref{eq:pseudo-awgn} is an AWGN
observation of the channel.
Combining its likelihood with the prior $q_{\rm tr}$ gives the posterior distribution $\pi_v(dH\mid R)$:
\begin{equation}
 \pi_v(dH\mid R)
 \propto\CN(\vect(R);\vect(H),v\I_D)q_{\rm tr}(dH).
 \label{eq:active-channel-posterior}
\end{equation}
The conditional mean and covariance are
\begin{equation}
 \begin{aligned}
 m(R,v)&=\int H\,\pi_v(dH\mid R),\\
 \bm\Sigma_H(R,v)&=\int \vect(H-m)\vect(H-m)^{\mathsf H}
                       \pi_v(dH\mid R).
 \end{aligned}
 \label{eq:conditional-channel-integrals}
\end{equation}
We denote the approximations to $m(R_k,v)$ and $\tr\bm\Sigma_H(R_k,v)/D$ by
$\mu_k$ and $t_k$, respectively.

Activity detection compares the hypotheses $R_k=W_k$ and $R_k=H_k+W_k$.
Marginalizing the channel under the active hypothesis yields the likelihood
$q_{1,v}$, whereas $q_{0,v}$ is the Gaussian noise density under the
inactive hypothesis:
\begin{equation}
 \begin{aligned}
 q_{1,v}(R)&=\int\CN(\vect(R);\vect(H),v\I_D)q_{\rm tr}(dH),\\
 q_{0,v}(R)&=\CN(\vect(R);\mathbf0,v\I_D).
 \end{aligned}
 \label{eq:query-densities}
\end{equation}
With prior activity probability $\rho$, Bayes' rule gives
\begin{equation}
 p^\star(R,v)=\frac{\rho q_{1,v}(R)}
 {(1-\rho)q_{0,v}(R)+\rho q_{1,v}(R)}.
 \label{eq:local-activity}
\end{equation}
Let $p_k$ denote the approximation to $p^\star(R_k,v)$ used in the joint
estimate below.

Under the two activity hypotheses, $X_k$ is either zero or equal to $H_k$.
Approximating the channel posterior under the active hypothesis by a Gaussian with mean $\mu_k$
and covariance $t_k\I_D$ gives the Bernoulli--Gaussian approximation
\cite[Secs.~III-C--III-D]{liu2018}, \cite[Sec.~III-B]{cai2026}
\begin{equation}
 \begin{aligned}
 \widetilde q_k(dX_k)&=(1-p_k)\delta_0(dX_k)\\
 &\quad+p_k\CN(\vect(X_k);\vect(\mu_k),t_k\I_D)\,dX_k,\\
 \widehat X_k&=p_k\mu_k.
 \end{aligned}
 \label{eq:mixture}
\end{equation}
Here $\delta_0$ denotes the probability measure concentrated at the zero tensor.

To compute the posterior covariance across antennas, we rearrange $\mu_k$ into
$\mathbf U_k\in\mathbb C^{M\times N^2}$, with one row for each antenna.
Averaging over the $N^2$ channel entries per antenna gives
\begin{equation}
 \mathbf C_{X,k}=p_kt_k\I_M+
 \frac{p_k(1-p_k)}{N^2}\mathbf U_k\mathbf U_k^{\mathsf H}.
 \label{eq:joint-spatial-covariance}
\end{equation}

The scalar posterior variance is then obtained by averaging its trace over
devices and antennas:
\begin{equation}
 \begin{aligned}
 \overline t_X&=\frac{1}{KM}\sum_k\tr\mathbf C_{X,k}\\
 &=\frac1K\sum_k\left[
 p_kt_k+p_k(1-p_k)\frac{\norm{\mu_k}_F^2}{D}\right].
 \end{aligned}
 \label{eq:joint-average-variance}
\end{equation}

To form the extrinsic message, we use a Gaussian approximation with mean
$\widehat X_k$ and common variance $\overline t_X$.
Let $b=\overline t_X/v$.
Dividing this approximation by the incoming Gaussian message, as in
\eqref{eq:linear-extrinsic}, gives
\begin{equation}
 \gamma_{\rm out}=\frac{vb}{1-b},\qquad
 X_{k,\rm out}=\frac{\widehat X_k-bR_k}{1-b}.
 \label{eq:nonlinear-extrinsic}
\end{equation}

At fixed $\mathbf C$, let $q_{\bm\Sigma}^{\mathbb R}$ denote the density of
$\mathbf u$.
The conditional mean is given by Tweedie's formula
\cite{efron2011,dytso2023}
\begin{equation}
 \mathbf m_{\mathbb R}(\mathbf u,\mathbf C)
 =\mathbf u+\bm\Sigma\nabla_{\mathbf u}
       \log q_{\bm\Sigma}^{\mathbb R}(\mathbf u).
 \label{eq:tweedie-mean}
\end{equation}

The conditional covariance $\mathbf P_{\mathbb
R}=\operatorname{Cov}(\mathbf h_{\mathbb R} \mid\mathbf u,\mathbf C)$ is
similarly related to the second-order score \cite{dytso2023},
\cite[Sec.~IV-A]{cai2026}:
\begin{equation}
 \mathbf P_{\mathbb R}
 =\bm\Sigma+\bm\Sigma
   \nabla_{\mathbf u}^2\log q_{\bm\Sigma}^{\mathbb R}(\mathbf u)
   \bm\Sigma.
 \label{eq:tweedie-covariance}
\end{equation}
Here the second-order score is the Hessian of the log density.

Let $S_\theta(\mathbf u,\mathbf C)$ approximate the first-order score, with
trainable parameters $\theta$.
The score of $q_{\bm\Sigma}^{\mathbb R}$ is unknown, whereas the
Gaussian perturbation in \eqref{eq:colored-query} has conditional
score $-\bm\Sigma^{-1}(\mathbf u-\mathbf h_{\mathbb R})$.
Denoising score matching \cite{vincent2011} therefore uses
\begin{equation}
 \mathcal L_{\rm DSM}(\theta)=
 \E\left[\frac{1}{2D}
 \norm{\bm\Sigma^{1/2}
 (S_\theta(\mathbf u,\mathbf C)
 +\bm\Sigma^{-1}(\mathbf u-\mathbf h_{\mathbb R}))}^2\right].
 \label{eq:denoising-score-objective}
\end{equation}
For each fixed $\mathbf C$, this differs from score matching weighted by $\bm\Sigma$ by a term independent of $\theta$.

To obtain the channel estimate directly, we parameterize the score as
$S_\theta=\bm\Sigma^{-1}(f_\theta-\mathbf u)$, where $f_\theta(\mathbf
u,\mathbf C)$ is a denoiser.
Substituting this relation into \eqref{eq:denoising-score-objective}
gives the training loss
\begin{equation}
 \mathcal L_{\rm ch}(\theta)=
 \E\left[\frac{1}{2D}
 \norm{\bm\Sigma^{-1/2}
       (f_\theta(\mathbf u,\mathbf C)-\mathbf h_{\mathbb R})}^2\right].
 \label{eq:first-loss}
\end{equation}

Differentiating \eqref{eq:tweedie-mean} with respect to $\mathbf u$ at fixed
$\mathbf C$ gives the Jacobian $\mathbf J_m=\partial\mathbf
m_{\mathbb R}/\partial\mathbf u =\I_{2D}+\bm\Sigma\nabla_{\mathbf u}^2 \log
q_{\bm\Sigma}^{\mathbb R}(\mathbf u)$.
Right-multiplying by $\bm\Sigma$ and using \eqref{eq:tweedie-covariance}, we
obtain \cite[Prop.~1]{dytso2023}
\begin{equation}
 \mathbf P_{\mathbb R}=\mathbf J_m\bm\Sigma,\qquad
 \tau^\star=\frac1D\tr(\mathbf J_m\bm\Sigma).
 \label{eq:mean-derivative-variance}
\end{equation}

We approximate the derivatives by finite differences and estimate the
trace by Monte Carlo averaging \cite{metzler2016}, with $f_\theta$ in
place of the conditional mean.
Let $\mathbf z_\ell$ be independent random sign vectors with $\E[\mathbf
z_\ell\mathbf z_\ell^{\mathsf T}]=\I_{2D}$, and define $\mathbf
w_\ell=\bm\Sigma^{1/2}\mathbf z_\ell$.
Using $L_z$ random directions and a finite-difference step
$\delta_{\rm FD}>0$, the resulting estimate is
\begin{equation}
 \begin{aligned}
 \Delta_\ell f_\theta
 &=f_\theta(\mathbf u+\delta_{\rm FD}\mathbf w_\ell,\mathbf C)
   -f_\theta(\mathbf u-\delta_{\rm FD}\mathbf w_\ell,\mathbf C),\\
 \widehat\tau_\theta(R,\mathbf C)
 &=\frac{1}{2\delta_{\rm FD} D L_z}\sum_{\ell=1}^{L_z}
       \mathbf w_\ell^{\mathsf T}\Delta_\ell f_\theta.
 \end{aligned}
 \label{eq:derivative-trace}
\end{equation}

Taking the log odds of \eqref{eq:local-activity} gives
\begin{equation}
 \log\frac{p^\star(R,v)}{1-p^\star(R,v)}
 =\log\frac{\rho}{1-\rho}
  +\log\frac{q_{1,v}(R)}{q_{0,v}(R)}.
 \label{eq:activity-log-odds}
\end{equation}
The inactive likelihood $q_{0,v}$ is known, whereas $q_{1,v}$ involves the
channel integral in \eqref{eq:query-densities}.
Only their ratio is needed in \eqref{eq:activity-log-odds}.
We learn this density ratio through binary classification using samples from
the full channel prior \cite{menon2016}.

The training data contain two classes with equal prior probability,
$\Pr(a=1)=\pi_{\rm tr}=1/2$, where $a\in\{0,1\}$.
For $a=1$, the observation is $R=H+W$ with $H\sim q_{\rm tr}$; for $a=0$, it
is $R=W$.
The noise satisfies $\vect(W)\sim\CN(\mathbf0,v\I_D)$ independently of $H$,
and both classes use the same sampling distribution of $v$.
The classifier has trainable parameters $\phi$. Its logit is learned by
minimizing the binary cross-entropy loss
\begin{equation}
 \begin{gathered}
 \mathcal L_{\rm act}(\phi)=
 \E[\log(1+e^{z_\phi})-a z_\phi],\\
 z_\phi=z_\phi(R,v,F_\theta(R,v\I_D)).
 \end{gathered}
 \label{eq:classifier-loss}
\end{equation}

The minimizer of the expected loss over all functions of $(R,v)$ is
the posterior log odds under the training distribution:
\begin{equation}
 z^\star(R,v)=\logit\pi_{\rm tr}
       +\log\frac{q_{1,v}(R)}{q_{0,v}(R)}.
 \label{eq:ideal-logit}
\end{equation}

Subtracting the training prior log odds therefore estimates the log density
ratio \cite[Sec.~4.2]{menon2016}.
With $F_k=F_\theta(R_k,v\I_D)$, inserting this estimate into
\eqref{eq:activity-log-odds} gives the activity probability
\begin{equation}
 \begin{gathered}
 \ell_k=z_\phi(R_k,v,F_k)-\logit\pi_{\rm tr},\\
 p_k=\sigmoid(\logit\rho+\ell_k),
 \end{gathered}
 \label{eq:activity-probability}
\end{equation}
where $\logit a=\log[a/(1-a)]$ and $\sigmoid b=(1+e^{-b})^{-1}$.
The activity prior $\rho$ enters through Bayes' rule, separately
from the learned density ratio.

We incorporate the estimated channel mean and variance into message passing through
a site approximation to the channel prior \cite[Sec.~2.1]{vehtari2020},
of the form $\CN(\vect(H_k);\vect(E_k),c_k\I_D)$.
Dividing the Gaussian posterior approximation with mean $F_k$ and variance
$\tau^{\rm post}$ by the input likelihood gives
\begin{equation}
 c_k=((\tau^{\rm post})^{-1}-v^{-1})^{-1},\qquad
 E_k=c_k\left(\frac{F_k}{\tau^{\rm post}}-\frac{R_k}{v}\right).
 \label{eq:site-update}
\end{equation}

Multiplying this site by the current Gaussian likelihood gives the
conditional channel mean and variance
\begin{equation}
 t_k=\frac{c_kv}{c_k+v},\qquad
 \mu_k=\frac{c_kR_k+vE_k}{c_k+v}.
 \label{eq:conditional-moments}
\end{equation}

Minimizing the expected Gaussian negative log likelihood over the input
variance $v$, with the current approximate posterior \eqref{eq:mixture}
held fixed \cite[Sec.~III-A]{vila2013}, gives
\begin{equation}
 v_{\rm tar}=\frac{1}{KD}\sum_{k=1}^K
 \norm{R_k-\widehat X_k}_F^2+\overline t_X.
 \label{eq:query-variance-target}
\end{equation}

At iteration $i$, we use $v^{(i)}=\kappa^{(i)}\bar v^{(i)}$, where $\bar
v^{(i)}$ denotes the damped MFLE variance.
With damping factor $\eta\in(0,1]$, the updated scaling factor is
\begin{equation}
 \kappa^{(i+1)}=(1-\eta)\kappa^{(i)}
       +\eta\frac{v_{\rm tar}^{(i)}}{\bar v^{(i)}}.
 \label{eq:query-variance-update}
\end{equation}

For normalization, we divide $(H_k,X_k,\mathbf Y,\mathbf W)$ by the root mean square $s$ of the training-channel entries and the noise variance by $s^2$, retaining their
symbols and leaving the pilot matrix unchanged.
For $i\geq2$, the MFLE output is damped as \cite[Sec.~V-B1]{cai2026}
\begin{equation}
 \begin{aligned}
 R_k^{(i)}&=(1-\eta)R_k^{(i-1)}+\eta R_{{\rm L},k}^{(i)},\\
 \bar v^{(i)}&=(1-\eta)\bar v^{(i-1)}+\eta v_{\rm L}^{(i)}.
 \end{aligned}
 \label{eq:input-damping}
\end{equation}

For numerical evaluation of \eqref{eq:nonlinear-extrinsic}, we replace
$b=\overline t_X/v$ by $b=\clip(\overline t_X/v,\varepsilon,1-\varepsilon)$,
where $0<\varepsilon<1/2$.
Here $\clip(x,a,b)=\min\{b,\max\{a,x\}\}$.
The feedback is then damped with the same damping factor:
\begin{equation}
 \begin{aligned}
 X_k^{{\rm pri},(i)}
 &=(1-\eta)X_k^{{\rm pri},(i-1)}+\eta X_{k,\rm out}^{(i)},\\
 \gamma^{(i)}
 &=(1-\eta)\gamma^{(i-1)}+\eta\gamma_{\rm out}^{(i)}.
 \end{aligned}
 \label{eq:output-damping}
\end{equation}

For fixed phases and $Q\leq KN$, the thin singular value decomposition
(SVD), $\widehat{\mathbf A}=\mathbf U\diag(s_1,\ldots,s_Q)\mathbf V^{\mathsf H}$,
is reused across iterations, where $s_a$ are the singular values.
The scalar updates in
\eqref{eq:linear-variance}--\eqref{eq:linear-extrinsic} can be written as
\begin{equation}
 f_{\rm L}=\frac{1}{KN}\sum_{a=1}^{Q}
 \frac{\gamma s_a^2}{\widehat\sigma^2+\gamma s_a^2},\qquad
 t_{\rm L}=\gamma(1-f_{\rm L}),\qquad
 v_{\rm L}=\frac{t_{\rm L}}{f_{\rm L}}.
 \label{eq:linear-fraction}
\end{equation}
